sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
   var serviceChoice = g_form.getValue('service');
   if(serviceChoice =='vpn' || serviceChoice == 'database') {
	g_form.setValue('assignment_group', '33b342aa834cd7103284c5a6feaad3cb');
   }
   else if(serviceChoice =='github' ) {
	g_form.setValue('assignment_group', 'afd4c22e834cd7103284c5a6feaad3b2');
   }
   else {
	g_form.setValue('assignment_group', '49958a6e834cd7103284c5a6feaad391');
   }

}
